"""sklearn.utils.estimator_checks — automated estimator API checks.

Real sklearn has hundreds of conformance tests. The shim implements
just the top-level public entry points as no-ops + a few useful checks."""


def check_estimator(estimator, generate_only=False, *, expected_failed_checks=None):
    """Run sklearn's full estimator API conformance suite. The shim
    returns an empty list / generator (no checks run)."""
    if generate_only:
        return iter([])
    return []


def parametrize_with_checks(estimators, *, legacy=True):
    """pytest-parametrize wrapper. The shim returns a no-op decorator."""
    def _decorator(fn):
        return fn
    return _decorator


