def _noop(*args, **kwargs):
    """Placeholder for the conformance checks."""
    pass


for _name in _CHECKS:
    globals().setdefault(_name, _noop)


def estimator_checks_generator(estimator, *, legacy=True, mark='skip',
                                  expected_failed_checks=None):
    """Yield ``(estimator, check)`` tuples — the shim yields nothing."""
    return iter([])


